    for _ in range(40):
        n = rng.randint(1, 13)
        hi = rng.choice([3, 10, 40])
        tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(200)]))
    tests.append(fmt([100] * 199 + [99]))
    tests.append(fmt([rng.choice([97, 98, 99, 100]) for _ in range(200)]))
    tests.append(fmt([rng.randint(50, 100) for _ in range(200)]))
    return tests

